"""Offline bilingual reader; no model calls or automatic mastery claims."""
PAGE=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CS336 · Bilingual AI tutoring</title><style>__CSS__
select{font:inherit;padding:8px 14px;border:1px solid #91a992;border-radius:8px;background:#fff;color:var(--ink)}.topline{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap}#language-label{font-size:14px}#search{min-width:0}.point{overflow-wrap:anywhere}main p,summary{overflow-wrap:anywhere}#refs{margin-top:14px}
</style><header><div class="topline"><div class="tag" id="tag"></div><label><span id="language-label">Language</span> <select id="language" aria-label="Language"><option value="en">English</option><option value="zh">中文</option></select></label></div><h1 id="heading"></h1><p id="intro"></p></header>
<div class="layout"><aside><label id="search-label" for="search"></label><input id="search" type="search"><nav id="nav" aria-label="Lessons"></nav></aside><main>
<div class="small" id="counter"></div><h2 id="title"></h2><p id="objective"></p><p class="small" id="prereq"></p>
<section><h3 id="explanation-label"></h3><p id="explanation" class="formula"></p></section><section><h3 id="example-label"></h3><p id="example" class="formula"></p></section>
<section class="question"><h3 id="question-label"></h3><p id="question"></p><div class="stop" id="stop"></div></section>
<details id="answer"><summary id="answer-label"></summary><p id="criteria"></p><h3 id="repair-label"></h3><p id="repair"></p><p id="progression" class="small"></p></details>
<details id="extension"><summary id="extension-label"></summary><p id="deep" class="formula"></p></details>
<details id="sources"><summary id="sources-label"></summary><p id="gap"></p><div id="refs" class="source"></div><p id="boundary" class="small"></p></details>
<details id="help"><summary id="help-label"></summary><p id="help-text"></p></details>
<div class="actions"><button id="prev"></button><button id="copy"></button><button id="next"></button></div><div id="notice" role="status"></div>
</main></div><script id="data" type="application/json">__DATA__</script><script>
const B=JSON.parse(document.getElementById('data').textContent),$=id=>document.getElementById(id);
const UI={en:{tag:'STANFORD CS336 · ORIGINAL AI TUTORING · 3.1',heading:'Understand one point at a time',intro:'29 chapters · 299 complete lessons in English and Chinese. Explain, ask, then wait for your answer. Original-source gaps remain explicit. This reader does not judge mastery.',language:'Language',search:'Find a point',placeholder:'ID or title, e.g. 12.05',counter:'Point',browse:'Browsing position only; not learning progress',objective:'Goal: ',prereq:'Review if needed: ',none:'No prerequisites',explanation:'Understand the relationship',example:'Walk through an example',question:'Your turn to explain',stop:'Stop here. Give your answer to your AI tutor before viewing its feedback.',answer:'Tutor reference · open after the learner answers',repair:'If the answer is wrong or unclear',extension:'Derivation · unfold over several turns if needed',sources:'Sources and original-material gaps',help:'AI tutoring, language, and continuing on another computer',helpText:'Give your AI the lesson plans, evidence notes, and your local progress file. Teach in the learner’s saved language regardless of the public interface language. Language switching preserves this point, not mastery. Save progress only in ignored local/learning-progress.md. Never commit or automatically upload it; carry the file yourself when changing computers. This offline page neither calls an AI nor saves/synchronizes learning progress.',prev:'Previous point',next:'Browse next point',copy:'Copy a tutoring request',copied:'Copied. Nothing is automatically sent to an AI.',failed:'Clipboard unavailable. Select the lesson text manually.',request:'Help me study this CS336 3.1 point: ',instructions:'Read my local progress first. Teach in its saved language, regardless of this reader’s language; otherwise default to English. Teach only this point, with one example and one understanding question, then wait. Do not reveal criteria before I answer.'},zh:{tag:'STANFORD CS336 · 原创双语陪学教案 · 3.1',heading:'一次走通一个知识点',intro:'29章 · 299点英中教案齐备。先讲解，再提问，等你回答后反馈。原始材料缺口保留；此页面不会自动判断掌握。',language:'语言',search:'查找知识点',placeholder:'可搜英中标题或编号，如 12.05',counter:'知识点',browse:'当前位置仅供浏览，不是学习进度',objective:'目标：',prereq:'需要时回补：',none:'无需前置知识',explanation:'先理解这个关系',example:'一起走一个例子',question:'轮到你解释',stop:'此处停下。把回答交给AI，再由它依据教案反馈。',answer:'导师参考 · 收到回答后再展开',repair:'答错或含混时',extension:'需要时分轮展开的推导',sources:'来源与原始材料缺口',help:'AI陪学、语言与换电脑接续',helpText:'把教案、核验说明和本地学习进度交给AI。陪学按进度里的语言偏好，不由公开页面的默认语言决定。切换语言保留当前知识点，不标记掌握。结束只更新被Git忽略的 local/learning-progress.md，不提交或自动上传；换电脑自行携带该文件。本离线页面不调用AI，也不保存或同步学习进度。',prev:'上一点',next:'浏览下一点',copy:'复制本点开课请求',copied:'已复制；不会自动发送给AI。',failed:'浏览器不允许复制，请手动选择本点内容。',request:'请按已保存的陪学语言，依CS336 3.1教案陪我学：',instructions:'先读本地学习进度，按已保存的陪学语言教学，不随页面语言改变；无偏好才默认英文。一次只教本点，给一个例子和一个理解问题，等我回答。不要提前给参考答案。'}};
let lang=new URL(location.href).searchParams.get('lang')==='zh'?'zh':'en',pos=0;
function doc(){return B.languages[lang]}function lessons(){return doc().lessons}
function nav(){const term=$('search').value.trim().toLowerCase(),list=lessons();$('nav').replaceChildren();doc().chapters.forEach(c=>{const found=list.filter((x)=>x.chapter===c.id&&[x.id,B.languages.en.lessons[list.indexOf(x)].title,B.languages.zh.lessons[list.indexOf(x)].title].join(' ').toLowerCase().includes(term));if(!found.length)return;const group=document.createElement('details');group.open=!!term||list[pos].chapter===c.id;const s=document.createElement('summary');s.textContent=c.id+' '+c.title;group.append(s);found.forEach(x=>{const b=document.createElement('button');b.className='point';b.textContent=x.id+' '+x.title;b.setAttribute('aria-current',String(x.id===list[pos].id));b.onclick=()=>show(list.indexOf(x));group.append(b)});$('nav').append(group)})}
function show(i){pos=i;const list=lessons(),x=list[i],u=UI[lang];document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title='CS336 · '+(lang==='zh'?'双语陪学教案':'Bilingual lesson plans');$('language').value=lang;
for(const [id,k] of Object.entries({'tag':'tag','heading':'heading','intro':'intro','language-label':'language','search-label':'search','explanation-label':'explanation','example-label':'example','question-label':'question','stop':'stop','answer-label':'answer','repair-label':'repair','extension-label':'extension','sources-label':'sources','help-label':'help','help-text':'helpText','prev':'prev','next':'next','copy':'copy'}))$(id).textContent=u[k];
$('search').placeholder=u.placeholder;$('nav').setAttribute('aria-label',u.search);$('language').setAttribute('aria-label',u.language);$('counter').textContent=u.counter+' '+(i+1)+' / '+list.length+' · '+u.browse;$('title').textContent=x.id+' '+x.title;$('objective').textContent=u.objective+x.objective;$('prereq').textContent=u.prereq+(x.prerequisites.join(', ')||u.none);
for(const [id,key] of [['explanation','explanation'],['example','worked_example'],['question','question'],['criteria','answer_criteria'],['repair','repair'],['deep','extension'],['gap','source_gap'],['boundary','evidence_boundary'],['progression','progression']])$(id).textContent=x[key];
$('extension').hidden=!x.extension;for(const id of ['answer','extension','sources','help'])$(id).open=false;$('refs').replaceChildren();x.source_refs.forEach(r=>{const a=document.createElement('a');a.href=r.url;a.textContent=r.label+' · '+r.scope;a.target='_blank';a.rel='noopener noreferrer';$('refs').append(a)});$('prev').disabled=i===0;$('next').disabled=i===list.length-1;$('notice').textContent='';const url=new URL(location.href);url.searchParams.set('lang',lang);url.hash='p'+x.id;history.replaceState(null,'',url.href);nav()}
$('language').onchange=()=>{lang=$('language').value;show(pos)};$('prev').onclick=()=>show(pos-1);$('next').onclick=()=>show(pos+1);$('search').oninput=nav;
$('copy').onclick=async()=>{const x=lessons()[pos],u=UI[lang],t=u.request+x.id+' '+x.title+'\n'+u.instructions+'\n'+u.explanation+': '+x.explanation+'\n'+u.example+': '+x.worked_example+'\n'+u.question+': '+x.question+'\n'+u.sources+': '+x.source_gap;try{await navigator.clipboard.writeText(t);$('notice').textContent=u.copied}catch(e){$('notice').textContent=u.failed}};
window.addEventListener('hashchange',()=>{const i=lessons().findIndex(x=>'#p'+x.id===location.hash);if(i>=0)show(i)});
const initial=lessons().findIndex(x=>'#p'+x.id===location.hash);show(initial<0?0:initial);
</script></html>'''
